    $('t-fair').textContent = f.fair; $('t-bul').textContent = f.bullet; $('t-avg').textContent = f.avgLife;
    $('t-refd').textContent = `a ${c.wal}-year bullet, valued the same way`; $('t-avgd').textContent = `the curve read at ${c.wal} years`;
    $('t-tim').textContent = f.timing; $('t-conv').textContent = f.convention;
    $('t-tim').className = 'n ' + (f.timing.startsWith('+') ? 'pos' : 'neg'); $('t-conv').className = 'n ' + (f.convention.startsWith('+') ? 'pos' : 'neg');
    $('t-benl').textContent = X ? `Benefit, after the agreed ${xLab(X)}` : 'Benefit'; $('t-ben').textContent = f.wedgeP;
    $('t-x').hidden = !X; $('t-x').textContent = X ? `The agreed ${xLab(X)} is added to the average-life price, so it changes the benefit by ${f.xEffect}.` : '';
